/// Every G02 custody transition in logical source order. Older issue/abandon records did
/// not retain account revisions; exact delivery receipts did.
pub(crate) fn cargo_mass_events(&self) -> Vec<FreightMassEvent> {
    let mut events = Vec::new();
    for job in self.data.jobs.iter().flatten() {
        events.push(FreightMassEvent {
            sequence: job.issue_sequence,
            revision: job.issue_account_revision,
            delta: 8,
            system: job.issuer.system,
            dock_sequence: Some(job.issuer.arrival_sequence),
        });
        let mut remaining = 8_i16;
        let mut sequence = job.issue_sequence;
        for transfer in job.transfers.iter().flatten() {
            let amount = transfer.mask.count_ones() as i16;
            remaining -= amount;
            sequence = transfer.sequence;
            events.push(FreightMassEvent {
                sequence,
                revision: Some(transfer.account_revision),
                delta: -amount,
                system: transfer.dock.system,
                dock_sequence: Some(transfer.dock.arrival_sequence),
            });
        }
        if job.status == JobStatus::Abandoned {
            events.push(FreightMassEvent {
                sequence: sequence.saturating_add(1),
                revision: job.abandoned_account_revision,
                delta: -remaining,
                system: AVENOR,
                dock_sequence: None,
            });
        }
    }
    events.sort_unstable_by_key(|event| event.sequence);
    events
}

/// Bind a retained passenger reception to the actual system travelled to before its berth.
pub(crate) fn validate_passenger_berth(
    &self,
    dock: DockContext,
    tick: u64,
) -> Result<(), SaveError> {
    self.spent_at(dock, tick)?;
    let count = usize::try_from(dock.visit().checked_sub(dock.sequence()).ok_or(INVALID)?)
        .map_err(|_| INVALID)?;
    let system = if count == 0 {
        SystemId::AVENOR
    } else {
        self.legs.get(count - 1).ok_or(INVALID)?.destination
    };
    if dock.system() != system {
        return Err(INVALID);
    }
    Ok(())
}

pub(crate) fn cargo_mass_events(&self) -> Vec<(u64, i16)> {
    self.receipts
        .iter()
        .filter_map(|r| {
            let (commodity, delta) = match r.event {
                Event::BoughtFood { .. } => (CommodityId::Food, 1),
                Event::SoldFood { .. } => (CommodityId::Food, -1),
                Event::BoughtCommodity { commodity, .. } => (commodity, 1),
                Event::SoldCommodity { commodity, .. } => (commodity, -1),
                Event::Refuelled { .. } => return None,
            };
            (commodity.unit() == super::CargoUnit::Tonne).then_some((r.revision, delta))
        })
        .collect()
}
